def authorize_read(actor, account_id):
    if actor.account_id != account_id:
        raise PermissionError('account')

def export(actor, account_id, store):
    authorize_read(actor, account_id)
    return store.read(account_id)

def preview(actor, account_id, store):
    return store.read(account_id)
